:root {
  /* Colors */
  --color-linen-canvas: #f8f7f5;
  --color-paper: #ffffff;
  --color-parchment-card: #f8f5f4;
  --color-quartz-quote: #f9f6f8;
  --color-forest-floor: #0c221d;
  --color-ink: #151515;
  --color-graphite-body: #151515cc;
  --color-ash-caption: #15151580;
  --color-fog-footer: #ffffff99;
  --color-steel-hairline: #15151533;
  --color-forest-signal: #29735c;
  --color-moss-label: #215b4b;
  --color-mint-tag: #bae0cf;

  /* Typography — Font Families */
  --font-mt-neue: "mt-neue-display", "Inter Display", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-mt-neue-text: "mt-neue-text", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-mt-sans: "mt-sans", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-mt-mono: "mt-mono", "JetBrains Mono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 11px;
  --leading-small: 1.5;
  --tracking-small: 0.66px;
  --text-caption: 13px;
  --leading-caption: 1.69;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.5;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 18px;
  --leading-body-lg: 1.5;
  --tracking-body-lg: 0px;
  --text-subheading: 21px;
  --leading-subheading: 1.3;
  --tracking-subheading: 0px;
  --text-heading-sm: 32px;
  --leading-heading-sm: 1.25;
  --tracking-heading-sm: 0px;
  --text-heading: 47px;
  --leading-heading: 1.25;
  --tracking-heading: 0px;
  --text-display: 71px;
  --leading-display: 1.1;
  --tracking-display: 0px;

  /* Typography — Weights */
  --font-weight-light: 330;
  --font-weight-light-2: 360;
  --font-weight-regular: 400;
  --font-weight-regular-2: 450;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-60: 60px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-120: 120px;

  /* Layout */
  --layout-page-max-width: 1200px;
  --layout-section-gap: 120px;
  --layout-card-padding: 48px;
  --layout-element-gap: 16px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 6px;
  --radius-xl: 8px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-inputs: 0px;
  --radius-buttons: 2px;
  --radius-tags: 2px;
  --radius-nav: 4px;
  --radius-small-cards: 6px;
  --radius-cards: 8px;
  --radius-pills: 9999px;

  /* Shadows */
  --shadow-subtle: inset 0 0 0 1px #151515;
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -2px rgba(0, 0, 0, 0.1);
  --shadow-lg: 0 20px 25px -5px rgba(0, 0, 0, 0.04), 0 8px 10px -6px rgba(0, 0, 0, 0.04);

  /* Surfaces */
  --surface-linen-canvas: #f8f7f5;
  --surface-paper: #ffffff;
  --surface-parchment-card: #f8f5f4;
  --surface-ink: #151515;
  --surface-forest-floor: #0c221d;
}

